+    if (!name || !name.trim()) {
+        throw new Error('Le nom du programme est obligatoire.');
+    }
+
+    if (!typeJira) {
+        throw new Error('Le type Jira est obligatoire.');
+    }
+
+    if (!responsable) {
+        throw new Error('Le responsable est obligatoire.');
+    }
+
+    /*
+     * Jira impose une clé de projet.
+     *
+     * Pour cette première version, nous générons
+     * automatiquement une clé à partir du nom.
+     */
+    const key = name
+        .normalize('NFD')
+        .replace(/[\u0300-\u036f]/g, '')
+        .replace(/[^a-zA-Z0-9]/g, '')
+        .toUpperCase()
+        .substring(0, 10);
+
+    if (!key) {
+        throw new Error(
+            'Impossible de générer une clé Jira à partir du nom du programme.'
+        );
+    }
+
+    const projectData = {
+        name: name.trim(),
+        key,
+        projectTypeKey: typeJira,
+        description: description || '',
+        leadAccountId: responsable,
+    };
+
+    /*
+     * L'axe stratégique correspond à la catégorie Jira.
+     */
+    if (axle) {
+        projectData.categoryId = Number(axle);
+    }
+
+    console.log(
+        '[createProgram] Payload envoyé à Jira :',
+        projectData
+    );
+
+    const response = await api
+        .asApp()
+        .requestJira(route`/rest/api/3/project`, {
+            method: 'POST',
+            headers: {
+                Accept: 'application/json',
+                'Content-Type': 'application/json',
+            },
+            body: JSON.stringify(projectData),
+        });
+
+    console.log(
+        '[createProgram] Jira status:',
+        response.status
+    );
+
+    const responseText = await response.text();
+
+    if (!response.ok) {
+        console.error(
+            '[createProgram] Jira error:',
+            responseText
+        );
+
+        throw new Error(
+            `Impossible de créer le projet Jira : ${response.status} ${responseText}`
+        );
+    }
+
+    const project = JSON.parse(responseText);
+
+    console.log(
+        '[createProgram] Projet Jira créé :',
+        project
+    );
+
+    return {
+        id: project.id,
+        key: project.key,
+        self: project.self,
+        name: name.trim(),
+    };
+});
